Here's a complete checkout screen for a Telegram Mini App. It's split into three files — types, the component, and the stylesheet — using Telegram's theme CSS variables (with sensible fallbacks) so it blends into light/dark themes, and it wires up the native Telegram `BackButton` when running inside Telegram while still rendering its own in-page back control for fallback/testing outside Telegram.

```tsx
// src/types/checkout.ts

export interface CartItem {
  id: string;
  name: string;
  imageUrl?: string;
  price: number; // price per unit, in the smallest readable currency unit (e.g. dollars)
  quantity: number;
  variant?: string; // e.g. "Size M / Black"
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment: string;
  postalCode: string;
  comment: string;
}

export interface CheckoutPayload {
  items: CartItem[];
  address: DeliveryAddress;
  subtotal: number;
  deliveryFee: number;
  total: number;
}

export const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};
```

```tsx
// src/screens/CheckoutScreen.tsx

import React, { useEffect, useMemo, useState } from 'react';
import {
  CartItem,
  DeliveryAddress,
  EMPTY_ADDRESS,
  CheckoutPayload,
} from '../types/checkout';
import './CheckoutScreen.css';

// Minimal shape of the Telegram WebApp API we rely on.
interface TelegramWebApp {
  BackButton: {
    show: () => void;
    hide: () => void;
    onClick: (cb: () => void) => void;
    offClick: (cb: () => void) => void;
  };
  HapticFeedback?: {
    notificationOccurred: (type: 'error' | 'success' | 'warning') => void;
    impactOccurred: (style: string) => void;
  };
  showAlert?: (message: string) => void;
}

declare global {
  interface Window {
    Telegram?: { WebApp?: TelegramWebApp };
  }
}

const FREE_DELIVERY_THRESHOLD = 50;
const DELIVERY_FEE = 4.99;
const CURRENCY = '$';

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

interface CheckoutScreenProps {
  cartItems: CartItem[];
  onBack: () => void;
  onPay: (payload: CheckoutPayload) => Promise<void> | void;
  initialAddress?: DeliveryAddress;
}

function formatMoney(value: number): string {
  return `${CURRENCY}${value.toFixed(2)}`;
}

function validate(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Enter your full name';
  }

  const digitsOnly = address.phone.replace(/[^\d]/g, '');
  if (!address.phone.trim()) {
    errors.phone = 'Enter a phone number';
  } else if (digitsOnly.length < 7) {
    errors.phone = 'Phone number looks too short';
  }

  if (!address.city.trim()) {
    errors.city = 'Enter a city';
  }

  if (!address.street.trim()) {
    errors.street = 'Enter a street address';
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = 'Enter a postal code';
  }

  return errors;
}

export default function CheckoutScreen({
  cartItems,
  onBack,
  onPay,
  initialAddress,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(
    initialAddress ?? EMPTY_ADDRESS
  );
  const [errors, setErrors] = useState<FieldErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const deliveryFee = subtotal === 0 || subtotal >= FREE_DELIVERY_THRESHOLD ? 0 : DELIVERY_FEE;
  const total = subtotal + deliveryFee;
  const isCartEmpty = cartItems.length === 0;

  // Wire up Telegram's native back button when available, falling back to
  // the in-page back button (rendered below) when running outside Telegram.
  useEffect(() => {
    const tg = window.Telegram?.WebApp;
    if (!tg) return;

    tg.BackButton.show();
    tg.BackButton.onClick(onBack);

    return () => {
      tg.BackButton.offClick(onBack);
      tg.BackButton.hide();
    };
  }, [onBack]);

  function handleChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  function handleBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate({ ...address }));
  }

  async function handlePay() {
    const validationErrors = validate(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      postalCode: true,
      comment: true,
    });

    if (Object.keys(validationErrors).length > 0 || isCartEmpty) {
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      return;
    }

    const payload: CheckoutPayload = {
      items: cartItems,
      address,
      subtotal,
      deliveryFee,
      total,
    };

    setPayError(null);
    setSubmitting(true);
    try {
      await onPay(payload);
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('success');
    } catch (err) {
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      setPayError(
        err instanceof Error ? err.message : 'Payment failed. Please try again.'
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <svg
            className="back-icon"
            viewBox="0 0 24 24"
            width="22"
            height="22"
            aria-hidden="true"
          >
            <path
              d="M15 18l-6-6 6-6"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <h1 className="checkout-title">Checkout</h1>
        <span className="checkout-header-spacer" aria-hidden="true" />
      </header>

      <main className="checkout-content">
        <section className="checkout-section" aria-labelledby="cart-heading">
          <h2 id="cart-heading" className="section-title">
            Your order
          </h2>

          {isCartEmpty ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {cartItems.map((item) => (
                <li className="cart-item" key={item.id}>
                  <div className="cart-item-thumb">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-thumb-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-info">
                    <span className="cart-item-name">{item.name}</span>
                    {item.variant && (
                      <span className="cart-item-variant">{item.variant}</span>
                    )}
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatMoney(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="order-summary">
            <div className="order-summary-row">
              <dt>Subtotal</dt>
              <dd>{formatMoney(subtotal)}</dd>
            </div>
            <div className="order-summary-row">
              <dt>Delivery</dt>
              <dd>{deliveryFee === 0 ? 'Free' : formatMoney(deliveryFee)}</dd>
            </div>
            <div className="order-summary-row order-summary-total">
              <dt>Total</dt>
              <dd>{formatMoney(total)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout-section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="section-title">
            Delivery address
          </h2>

          <form className="address-form" noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={(e) => handleChange('fullName', e.target.value)}
                onBlur={() => handleBlur('fullName')}
                aria-invalid={Boolean(touched.fullName && errors.fullName)}
                className={touched.fullName && errors.fullName ? 'input-error' : ''}
              />
              {touched.fullName && errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                placeholder="+1 555 123 4567"
                value={address.phone}
                onChange={(e) => handleChange('phone', e.target.value)}
                onBlur={() => handleBlur('phone')}
                aria-invalid={Boolean(touched.phone && errors.phone)}
                className={touched.phone && errors.phone ? 'input-error' : ''}
              />
              {touched.phone && errors.phone && (
                <span className="field-error">{errors.phone}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={(e) => handleChange('city', e.target.value)}
                  onBlur={() => handleBlur('city')}
                  aria-invalid={Boolean(touched.city && errors.city)}
                  className={touched.city && errors.city ? 'input-error' : ''}
                />
                {touched.city && errors.city && (
                  <span className="field-error">{errors.city}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={(e) => handleChange('postalCode', e.target.value)}
                  onBlur={() => handleBlur('postalCode')}
                  aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
                  className={touched.postalCode && errors.postalCode ? 'input-error' : ''}
                />
                {touched.postalCode && errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                autoComplete="address-line1"
                value={address.street}
                onChange={(e) => handleChange('street', e.target.value)}
                onBlur={() => handleBlur('street')}
                aria-invalid={Boolean(touched.street && errors.street)}
                className={touched.street && errors.street ? 'input-error' : ''}
              />
              {touched.street && errors.street && (
                <span className="field-error">{errors.street}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="apartment">Apartment / suite (optional)</label>
              <input
                id="apartment"
                type="text"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={(e) => handleChange('apartment', e.target.value)}
              />
            </div>

            <div className="form-field">
              <label htmlFor="comment">Delivery notes (optional)</label>
              <textarea
                id="comment"
                rows={2}
                value={address.comment}
                onChange={(e) => handleChange('comment', e.target.value)}
                placeholder="E.g. gate code, preferred time window..."
              />
            </div>
          </form>
        </section>

        {payError && <p className="pay-error" role="alert">{payError}</p>}
      </main>

      <footer className="checkout-footer">
        <button
          type="button"
          className="pay-button"
          onClick={handlePay}
          disabled={submitting || isCartEmpty}
        >
          {submitting ? (
            <span className="pay-spinner" aria-hidden="true" />
          ) : (
            <span>Pay {formatMoney(total)}</span>
          )}
        </button>
      </footer>
    </div>
  );
}
```

